values ('aaaa0002-0000-4000-8000-000000000005', 'fr', 'fr', 'French B2 — Upper Intermediate', 'Reach upper-intermediate French: defend an argument, decode complex media, negotiate, and write formal correspondence. This CEFR B2 course follows the Council of Europe''s B2 level descriptors.', 'B2', 'work', 13, true, 'language', '{aaaa0002-0000-4000-8000-000000000003}')
